"""Where uploaded files live. Local disk in development; an S3-compatible bucket can implement
the same interface for production.
"""

import os
import re
import uuid
from functools import lru_cache
from pathlib import Path
from typing import Protocol

from app.core.config import get_settings

# Keys are generated by the server: "<owner uuid>/<document uuid>.pdf". Anything else is refused,
# so a key can never contain "..", an absolute path or a user-chosen name.
_KEY_PATTERN = re.compile(r"^[0-9a-f-]{36}/[0-9a-f-]{36}\.pdf$")


class Storage(Protocol):
    def save(self, key: str, data: bytes) -> None: ...

    def path(self, key: str) -> Path: ...

    def delete(self, key: str) -> None: ...


def make_key(owner_id: uuid.UUID, document_id: uuid.UUID) -> str:
    return f"{owner_id}/{document_id}.pdf"


class LocalStorage:
    def __init__(self, root: Path) -> None:
        self.root = root.resolve()

    def path(self, key: str) -> Path:
        if not _KEY_PATTERN.match(key):
            raise ValueError(f"Invalid storage key: {key!r}")
        return self.root / key

    def save(self, key: str, data: bytes) -> None:
        target = self.path(key)
        target.parent.mkdir(parents=True, exist_ok=True)
        # Write to a temporary file, then rename: a crash never leaves a half-written PDF behind.
        temporary = target.with_suffix(".part")
        temporary.write_bytes(data)
        os.replace(temporary, target)

    def delete(self, key: str) -> None:
        self.path(key).unlink(missing_ok=True)


@lru_cache
def get_storage() -> Storage:
    return LocalStorage(Path(get_settings().storage_dir))
